package com.example.complaintmanagement.exception;
import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.LocalDateTime; import java.util.stream.Collectors;
@RestControllerAdvice public class GlobalExceptionHandler { private ResponseEntity<ErrorResponse> e(HttpStatus s,String m,HttpServletRequest r){return ResponseEntity.status(s).body(new ErrorResponse(LocalDateTime.now(),s.value(),s.getReasonPhrase(),m,r.getRequestURI()));}
@ExceptionHandler(ResourceNotFoundException.class) ResponseEntity<?> nf(ResourceNotFoundException x,HttpServletRequest r){return e(HttpStatus.NOT_FOUND,x.getMessage(),r);} @ExceptionHandler(BadRequestException.class) ResponseEntity<?> br(BadRequestException x,HttpServletRequest r){return e(HttpStatus.BAD_REQUEST,x.getMessage(),r);} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<?> val(MethodArgumentNotValidException x,HttpServletRequest r){String m=x.getBindingResult().getFieldErrors().stream().map(a->a.getField()+": "+a.getDefaultMessage()).collect(Collectors.joining("; "));return e(HttpStatus.BAD_REQUEST,m,r);} @ExceptionHandler(Exception.class) ResponseEntity<?> all(Exception x,HttpServletRequest r){return e(HttpStatus.INTERNAL_SERVER_ERROR,x.getMessage()==null?"Unexpected server error":x.getMessage(),r);} }
